window.RAB_MAP={"person":{"title":"Person & intent","purpose":"A continuing relationship shaped by the person’s own goals.","inputs":"Intent; arrival stage; household; constraints; stated preferences.","outputs":"Editable personal context; priorities; consent choices.","scope":"Working onboarding, one fictional newcomer; broader personas represented in architecture.","proto":true},"assistant":{"title":"Personal companion","purpose":"One conversational entry point across life domains.","inputs":"Confirmed context; user questions; reminders; unresolved actions.","outputs":"Briefings; clarifying questions; explanations; follow-through.","scope":"Working text conversation. Voice is a later interface extension.","proto":true},"identity":{"title":"Companion identity","purpose":"A person names and shapes their own AI companion.","inputs":"Chosen name; appearance; voice; humour; directness.","outputs":"A consistent character and genuinely adjustable behaviour.","scope":"Prototype: name and communication preferences; does not impersonate a real loved one.","proto":true},"behaviour":{"title":"Behavioural adaptation","purpose":"Adapt support to stated needs and correctable interpretations.","inputs":"User-described state; preferences; feedback; current circumstances.","outputs":"Appropriate tone, pace and level of detail.","scope":"Prototype: explicit preferences and user-reported state; no diagnosis or covert psychological scoring.","proto":true},"initiative":{"title":"Proactive attention","purpose":"Start useful conversations and follow through without ritual permission prompts.","inputs":"Deadlines; unresolved matters; chosen quiet hours; prior feedback.","outputs":"Timely check-ins; gentle nudges; fewer unnecessary interruptions.","scope":"Prototype: event-driven prompts; not now is respected. External actions still need a clear go-ahead.","proto":true},"private":{"title":"Private companion space","purpose":"Keep personal conversation and memory separate from official service records.","inputs":"Private conversation; goals; preferences; personal reflections.","outputs":"Support for the individual; editable memory; deletion and pause controls.","scope":"Proposed architectural boundary: separate storage and access; must be implemented and tested before privacy claims.","proto":true},"official":{"title":"City service space","purpose":"Handle the specific information required for an official service.","inputs":"Service request; required fields; approved identifiers.","outputs":"Service record and authoritative status where connected.","scope":"Prototype: fictional records and public links; requirements explained per service.","proto":false},"bridge":{"title":"Selective sharing bridge","purpose":"Transfer only fields needed for one named purpose.","inputs":"Named recipient; purpose; field list; user go-ahead; expiry where applicable.","outputs":"Scoped request and a receipt of what was shared.","scope":"Prototype: inspectable simulated handoff; no private conversation or psychological profile included.","proto":true},"inbound":{"title":"Official updates to companion","purpose":"Bring a selected service update into the personal journey.","inputs":"Authorised appointment status or service reference.","outputs":"Reminder and dependent plan changes.","scope":"Receiving a status never grants the service access to personal memory.","proto":true},"receipt":{"title":"What is shared","purpose":"Make each exchange visible and understandable.","inputs":"Recipient; fields; purpose; time; connection state.","outputs":"Sharing history and controls for future access.","scope":"Prototype: simulated receipts; disconnecting does not erase records already lawfully held by recipients.","proto":true},"participation":{"title":"Independent participation","purpose":"Separate official-service use from the optional personal companion.","inputs":"Choice to use services, personal memory or wellbeing features.","outputs":"Independent controls without bundling intimate disclosure into service access.","scope":"Proposed policy: government adoption is not assumed to make companion use compulsory.","proto":true},"reporting":{"title":"Aggregate reporting boundary","purpose":"Evaluate service outcomes without exporting private life.","inputs":"Minimised, appropriately governed service milestone events.","outputs":"Cohort completion, delays and service friction; small-group suppression.","scope":"Prototype: synthetic cohort only; exclude private text, emotional profiles and named employer allegations.","proto":true},"operator":{"title":"Operator responsibilities","purpose":"Define who runs each space and who can access it.","inputs":"Hosting decisions; service roles; security and legal requirements.","outputs":"Separate identities, credentials, logs and narrowly controlled support access.","scope":"Future agreement: sponsorship gives no blanket access; no absolute secrecy claim.","proto":false},"familyview":{"title":"Family / delegate","purpose":"Coordinate explicitly shared responsibilities.","inputs":"Invitations and permissions for selected tasks.","outputs":"Shared actions, responsible person and revocable access.","scope":"Future; separate private profiles, no automatic household-wide access.","proto":false},"partners":{"title":"Partner workspace","purpose":"Receive narrowly scoped requests and provide status updates.","inputs":"Authorised handoffs; service reference; consent.","outputs":"Acknowledgements; progress; completion evidence.","scope":"Future employer/provider access. No access to private conversations.","proto":false},"ops":{"title":"Operations console","purpose":"Maintain reliable resources and handle exceptions.","inputs":"Stale sources; reported errors; unresolved cases.","outputs":"Catalogue corrections; escalations; support history.","scope":"Prototype catalogue maintained manually; full console later.","proto":false},"sponsor":{"title":"Institutional outcomes","purpose":"Evaluate whether the service reduces effort and unresolved delays.","inputs":"Aggregated milestone events; evidence status; feedback.","outputs":"Completion rates; elapsed time; obstacles; data-quality limits.","scope":"Labelled sample cohort only. No private conversations or employer misconduct rankings.","proto":true},"residency":{"title":"Arrival & residency","purpose":"Coordinate documents, recorded expiry dates and appointment dependencies.","inputs":"User-entered dates; employer arrangements; authoritative resources.","outputs":"Reminders; document tasks; appointment follow-ups.","scope":"Prototype: appointment status and recorded-date reminders. No eligibility determination.","proto":true},"work":{"title":"Employment & income","purpose":"Carry agreed onboarding and income expectations into the journey.","inputs":"User-stated salary date; onboarding milestones; reported updates.","outputs":"Clarification; reviewed follow-up draft; linked plan changes.","scope":"Prototype: user-reported delay. Unknown status is never proof of employer failure.","proto":true},"housing":{"title":"Home & household","purpose":"Coordinate temporary and permanent accommodation and household setup.","inputs":"Accommodation end date; budget; location; commitments.","outputs":"Continuity actions; viewing tasks; moving and utility dependencies.","scope":"Prototype: temporary accommodation expiry and continuity planning.","proto":true},"transport":{"title":"Transport & mobility","purpose":"Adapt everyday travel to work, home and affordability.","inputs":"Locations; schedule; preferences; constraints.","outputs":"Commute options; transport tasks; revised travel plan.","scope":"Future connected transport data; initial resource links only.","proto":false},"money":{"title":"Money & commitments","purpose":"Make known upcoming commitments visible as circumstances change.","inputs":"User-entered income expectations; essential costs; due dates.","outputs":"Cash-flow reminders; optional spending revisions.","scope":"Prototype: known commitments only; no bank connection or investment advice.","proto":true},"health":{"title":"Health & wellbeing","purpose":"Coordinate administrative care needs and preferred pace of support.","inputs":"Appointments; insurance tasks; user preferences.","outputs":"Scheduling actions; reminders; care-service handoffs.","scope":"Medical appointment demonstrated under residency; wider healthcare support later.","proto":false},"education":{"title":"Family & education","purpose":"Coordinate family arrival, schooling and childcare dependencies.","inputs":"Household needs; ages when necessary; target dates; consent.","outputs":"Family tasks; education-service handoffs.","scope":"Future; no school placement or eligibility claims.","proto":false},"belong":{"title":"Community & belonging","purpose":"Connect interests and comfort with participation in city life.","inputs":"Stated interests; availability; budget; language preference; feedback.","outputs":"Relevant activities; saved communities; participation follow-up.","scope":"Prototype: one sourced community option; no inferred sensitive personality profiling.","proto":true},"growth":{"title":"Learning & career","purpose":"Connect stated ambitions to learning and opportunities.","inputs":"Goals; skills the person chooses to share; availability.","outputs":"Learning path; professional events; opportunity handoffs.","scope":"Future; employment eligibility verified separately.","proto":false},"business":{"title":"Business & investment","purpose":"Support exploration, establishment and professional connections.","inputs":"Business intent; stage; sector; evidence needs.","outputs":"Market-entry tasks; programme and adviser handoffs.","scope":"Future; no investment recommendation or official approval.","proto":false},"memory":{"title":"Context & memory","purpose":"Keep confirmed facts consistent across sessions and domains.","inputs":"User confirmations; corrections; authorised updates.","outputs":"Versioned profile; preferences; fact provenance.","scope":"Current build: device-local profile and conversation memory; user-reported facts and simulated updates remain distinct.","proto":true},"journey":{"title":"Journey & dependencies","purpose":"Maintain the relationship between tasks, dates and outcomes.","inputs":"Milestones; prerequisites; context; completion events.","outputs":"Feasible next actions; blocked steps; affected dependencies.","scope":"Current build: ready, completed and future milestones, with temporary snoozing; broader dependency states are proposed.","proto":true},"events":{"title":"Events & reminders","purpose":"React to dates and updates without requiring a new question.","inputs":"User updates; due dates; optional authorised connector events.","outputs":"Deduplicated events; reminders; replanning triggers.","scope":"Working date checks while app is active; accelerated demo clock. Background delivery later.","proto":true},"planner":{"title":"Planning & recommendations","purpose":"Choose useful actions across domains from supported resources.","inputs":"Context; dependencies; catalogue; event; user preferences.","outputs":"Structured plan proposal and reasons.","scope":"Current build: finite scenario responses and deterministic prioritisation. Live LLM integration is a future step; no fabricated services.","proto":true},"evidence":{"title":"Resources & evidence","purpose":"Maintain a traceable basis for recommendations.","inputs":"Source URLs; scope; last-checked dates; resource metadata.","outputs":"Citable resources; freshness flags; evidence status.","scope":"Small manually checked catalogue. Listed provider does not mean guaranteed provider.","proto":true},"validate":{"title":"Validation & review","purpose":"Check proposed plan changes before accepting them.","inputs":"Proposed actions; allowed resources; current task state; permissions.","outputs":"Accepted revision or clarification / review request.","scope":"Working checks for resource IDs, dates, dependencies and preserved completions.","proto":true},"actions":{"title":"Actions & handoffs","purpose":"Turn a next step into a controlled action.","inputs":"Approved plan; required permissions; destination.","outputs":"External link; reminder; reviewed draft; authorised transaction.","scope":"Links and drafts work. No automatic email, booking, payment or submission.","proto":true},"history":{"title":"Progress & history","purpose":"Retain what happened and why the plan changed.","inputs":"Task transitions; evidence; user feedback; revisions.","outputs":"Before/after plan; completion record; reminder cancellation.","scope":"Working revision log; self-reported and externally verified remain distinct.","proto":true},"gov":{"title":"Government services","purpose":"Potential official-service and status connections.","inputs":"Entity-approved access; service references; permitted identifiers.","outputs":"Authoritative handoff or scoped status event.","scope":"Prototype: public links and labelled simulated events. No confirmed TAMM integration.","proto":false},"employer":{"title":"Employers & HR","purpose":"Potential onboarding and employment-status connections.","inputs":"Consent; agreed interface; scoped request.","outputs":"Acknowledgement or verified status.","scope":"Prototype: fictional status feed; user reports remain separately labelled.","proto":false},"providers":{"title":"Private service providers","purpose":"Potential housing, utilities, mobility and appointment connections.","inputs":"Authorised request and minimum necessary context.","outputs":"Options; acknowledgements; service status.","scope":"Prototype: selected links only; no inventory, availability or trust guarantee.","proto":false},"communities":{"title":"Community & opportunity sources","purpose":"Supply participation and growth opportunities.","inputs":"Public information or authorised feeds.","outputs":"Activities; learning; events; relevant opportunities.","scope":"Prototype: curated records; no live availability claim.","proto":false},"control":{"title":"Consent & access","purpose":"Give people control of their information and external actions.","inputs":"Connection permissions; notification preferences; sharing decisions.","outputs":"Scoped access; revocation; action approvals.","scope":"Working preferences and approval states; institutional access simulated.","proto":true},"security":{"title":"Security & deployment","purpose":"Make future institutional operation assessable.","inputs":"Data classification; sponsor requirements; threat model.","outputs":"Hosting design; access controls; retention; incident and recovery plan.","scope":"Production security and sovereign deployment require separate implementation and review.","proto":false},"assurance":{"title":"Accountability & quality","purpose":"Keep AI behaviour observable and correctable.","inputs":"Sources; test scenarios; incidents; user disputes.","outputs":"Audit trail; human escalation; error corrections; model evaluation.","scope":"Prototype: provenance, change log and uncertainty states. Wider operations later.","proto":true},"measure":{"title":"Measurement contract","purpose":"Define success before collecting pilot results.","inputs":"Agreed milestone definitions; baseline; consented events.","outputs":"Comparable outcomes with denominators and evidence quality.","scope":"Demo metrics only until a real pilot exists.","proto":true},"screen1":{"title":"01 · Welcome & context","purpose":"Capture enough information to begin useful support.","inputs":"Goal; arrival date; accommodation end; expected salary; appointment status; interests.","outputs":"Confirmed editable profile and initial event set.","scope":"Acceptance: corrections persist after reload.","proto":true},"screen2":{"title":"02 · Today & assistant","purpose":"Present the next three priorities with conversation alongside.","inputs":"Profile; event queue; validated plan.","outputs":"Action cards; explanations; clarifying conversation.","scope":"Acceptance: priorities change with relevant inputs.","proto":true},"screen3":{"title":"03 · Journey & essentials","purpose":"Show the 90-day path and the facts that support it.","inputs":"Tasks; dates; dependencies; evidence status.","outputs":"Timeline; blocked steps; editable essentials.","scope":"Acceptance: completed work survives replanning.","proto":true},"screen4":{"title":"04 · Action detail","purpose":"Make one recommendation actionable and inspectable.","inputs":"Action; reason; source; prerequisites; destination.","outputs":"Service link; follow-up draft; reported completion.","scope":"Acceptance: draft needs approval; link is a real catalogue entry.","proto":true},"screen5":{"title":"05 · Change & replan","purpose":"Make cross-domain reasoning visible.","inputs":"User-reported income delay; accommodation deadline; unconfirmed appointment.","outputs":"Clarification, affected domains and explained plan revision.","scope":"Acceptance: uncertain information stays uncertain; no allegation or auto-send.","proto":true},"screen6":{"title":"06 · Close the loop","purpose":"Update the assistant after progress.","inputs":"User confirms an appointment or accommodation arrangement.","outputs":"Task update; cancelled obsolete reminders; next action.","scope":"Acceptance: duplicate or outdated reminders do not reappear.","proto":true},"build":{"title":"Build order","purpose":"Implement the selected section from shared records outward.","inputs":"Architecture and prototype acceptance criteria.","outputs":"Data model → catalogue → journey rules → screens → AI → scenario tests.","scope":"Core records: Profile, Consent, Resource, Task, Event, Recommendation, Revision, ActionLog.","proto":true},"tests":{"title":"Demonstration checks","purpose":"Validate behaviour beyond the happy path.","inputs":"Missing dates; conflicting facts; repeat events; AI outage; stale resource; revoked permission.","outputs":"Clarification, deduplication, safe fallback and visible limitations.","scope":"Pass: no invented resource, lost completion, duplicate action or silent external submission.","proto":true}};